"use client";
import React from "react";
import { motion } from "framer-motion";

const DisplayCards = ({ cards = [] }) => {
  return (
    <div className="flex min-h-[400px] w-full items-center justify-center">
      <div className="relative w-full max-w-4xl">
        <div className="relative" style={{ gridTemplateColumns: "1fr 1fr 1fr", gridTemplateRows: "auto", gridTemplateAreas: "\"stack stack stack\"" }}>
          {cards.map((card, index) => (
            <motion.div
              key={index}
              initial={{ opacity: 0, y: 50 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: index * 0.15 }}
              className="relative overflow-hidden rounded-2xl p-6"
              style={{
                gridArea: "stack",
                zIndex: cards.length - index,
                transform: `translateX(${index * 40}px) translateY(${index * 30}px)`,
              }}
              whileHover={{
                y: -40 + (index * -10),
                transition: { duration: 0.4, ease: "easeOut" },
              }}
            >
              {/* Card background with gradient */}
              <div
                className="absolute inset-0 rounded-2xl"
                style={{
                  background: card.bgGradient || "linear-gradient(135deg, #1a080a 0%, #2a1520 100%)",
                  opacity: 0.95,
                }}
              />

              {/* Decorative top border */}
              <div
                className="absolute top-0 left-6 right-6 h-1 rounded-b-full"
                style={{ background: card.accentColor || "#d4af37" }}
              />

              {/* Card content */}
              <div className="relative z-10">
                {/* Icon */}
                <div
                  className="mb-4 flex h-12 w-12 items-center justify-center rounded-xl"
                  style={{
                    background: `${card.accentColor || "#d4af37"}20`,
                    color: card.accentColor || "#d4af37",
                  }}
                >
                  {card.icon}
                </div>

                {/* Badge */}
                <div className="mb-3 flex items-center gap-2">
                  <span
                    className="text-xs font-semibold uppercase tracking-wider px-3 py-1 rounded-full"
                    style={{
                      background: `${card.accentColor || "#d4af37"}20`,
                      color: card.accentColor || "#d4af37",
                    }}
                  >
                    {card.badge}
                  </span>
                  <span className="text-xs" style={{ color: "rgba(255,255,255,0.5)" }}>
                    {card.date}
                  </span>
                </div>

                {/* Title */}
                <h3
                  className="text-xl md:text-2xl font-semibold mb-2"
                  style={{ color: card.titleColor || "#ffffff", fontFamily: "Cormorant Garamond, serif" }}
                >
                  {card.title}
                </h3>

                {/* Description */}
                <p className="text-sm leading-relaxed mb-4" style={{ color: "rgba(255,255,255,0.7)" }}>
                  {card.description}
                </p>

                {/* CTA Link */}
                <div className="flex items-center gap-2">
                  <span className="text-sm font-medium" style={{ color: card.accentColor || "#d4af37" }}>
                    {card.cta || "Learn more"}
                  </span>
                  <svg
                    width="16"
                    height="16"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke={card.accentColor || "#d4af37"}
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    className="transition-transform group-hover:translate-x-1"
                  >
                    <path d="M5 12h14M12 5l7 7-7 7" />
                  </svg>
                </div>
              </div>

              {/* Decorative corner elements */}
              <div
                className="absolute bottom-4 right-4 w-16 h-16 opacity-10"
                style={{
                  borderBottom: `2px solid ${card.accentColor || "#d4af37"}`,
                  borderRight: `2px solid ${card.accentColor || "#d4af37"}`,
                }}
              />

              {/* Hover glow effect */}
              <div
                className="absolute inset-0 rounded-2xl opacity-0 transition-opacity duration-500 pointer-events-none"
                style={{
                  boxShadow: `0 0 40px ${card.accentColor || "#d4af37"}40`,
                }}
                data-hover-glow
              />
            </motion.div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default DisplayCards;
